res = await self.shell.run("""set -euxo pipefail
cd /workspace/repo/libarchive
# maybe configure source has generated scripts?
ls -l configure || true
./configure --disable-shared --enable-static --without-openssl --without-xml2 --without-lzma --without-bz2 --without-lzo2 --without-lz4 --without-zstd CFLAGS='-g -O0 -fsanitize=address,undefined -fno-omit-frame-pointer' CXXFLAGS='-g -O0 -fsanitize=address,undefined -fno-omit-frame-pointer' LDFLAGS='-fsanitize=address,undefined' >/tmp/config.log 2>&1
make -j2 libarchive.la >/tmp/make.log 2>&1
cd /workspace/repo
cat > /tmp/test_read.c <<'C'
#include <archive.h>
#include <archive_entry.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
int main(int argc, char**argv){
 if(argc<2) return 2;
 struct archive *a=archive_read_new();
 archive_read_support_filter_all(a); archive_read_support_format_all(a);
 int r=archive_read_open_filename(a, argv[1], 10240);
 fprintf(stderr,"open r=%d err=%s\n", r, archive_error_string(a));
 struct archive_entry* e;
 while((r=archive_read_next_header(a,&e))==ARCHIVE_OK){
   fprintf(stderr,"header ok name=%s size=%lld\n", archive_entry_pathname(e),(long long)archive_entry_size(e));
   char buf[4096]; la_ssize_t n;
   while((n=archive_read_data(a,buf,sizeof(buf)))>0){ fprintf(stderr,"read %ld\n",(long)n); }
   fprintf(stderr,"data ret=%ld err=%s\n",(long)n,archive_error_string(a));
 }
 fprintf(stderr,"next ret=%d err=%s\n", r, archive_error_string(a));
 archive_read_free(a);
 return 0;
}
